create schema if not exists integrarp;
create table if not exists integrarp.formulario_definicao (id uuid primary key, tenant_id uuid not null, nome text not null, descricao text, publicado boolean not null default false, criado_em timestamptz not null default now());
create table if not exists integrarp.formulario_versao (id uuid primary key, formulario_id uuid not null references integrarp.formulario_definicao(id), numero int not null, status text not null, criado_em timestamptz not null default now(), publicado_em timestamptz);
create table if not exists integrarp.formulario_secao (id uuid primary key, versao_id uuid not null references integrarp.formulario_versao(id), titulo text not null, ordem int not null, descricao text);
create table if not exists integrarp.formulario_campo (id uuid primary key, secao_id uuid not null references integrarp.formulario_secao(id), nome text not null, rotulo text not null, tipo text not null, ordem int not null, obrigatorio boolean not null default false, mascara text, regex_validacao text, valor_padrao text, opcoes_json jsonb, visibilidade_json jsonb, calculo_json jsonb, ajuda text);
create table if not exists integrarp.formulario_regra (id uuid primary key, versao_id uuid not null references integrarp.formulario_versao(id), tipo text not null, expressao_json jsonb not null, acao_json jsonb not null);
create table if not exists integrarp.formulario_resposta (id uuid primary key, tenant_id uuid not null, versao_id uuid not null references integrarp.formulario_versao(id), entidade_tipo text not null, entidade_id uuid, criado_por uuid not null, criado_em timestamptz not null default now());
create table if not exists integrarp.formulario_resposta_campo (id uuid primary key, resposta_id uuid not null references integrarp.formulario_resposta(id), campo_id uuid not null references integrarp.formulario_campo(id), valor_json jsonb);
create table if not exists integrarp.formulario_template (id uuid primary key, tenant_id uuid not null, nome text not null, template_json jsonb not null);
create table if not exists integrarp.formulario_validacao_log (id uuid primary key, tenant_id uuid not null, formulario_id uuid, mensagem text not null, criado_em timestamptz not null default now());
create table if not exists integrarp.automacao_regra (id uuid primary key, tenant_id uuid not null, nome text not null, habilitada boolean not null default false, criado_em timestamptz not null default now());
create table if not exists integrarp.automacao_gatilho (id uuid primary key, regra_id uuid not null references integrarp.automacao_regra(id), tipo text not null, configuracao_json jsonb);
create table if not exists integrarp.automacao_condicao (id uuid primary key, regra_id uuid not null references integrarp.automacao_regra(id), tipo text not null, campo text not null, valor_esperado text);
create table if not exists integrarp.automacao_acao (id uuid primary key, regra_id uuid not null references integrarp.automacao_regra(id), tipo text not null, configuracao_json jsonb not null, ordem int not null default 1);
create table if not exists integrarp.automacao_execucao (id uuid primary key, regra_id uuid not null references integrarp.automacao_regra(id), tenant_id uuid not null, status text not null, tentativas int not null default 0, criado_em timestamptz not null default now(), finalizado_em timestamptz);
create table if not exists integrarp.automacao_execucao_log (id uuid primary key, execucao_id uuid not null references integrarp.automacao_execucao(id), nivel text not null, mensagem text not null, criado_em timestamptz not null default now());
create table if not exists integrarp.anexo_arquivo (id uuid primary key, tenant_id uuid not null, nome_arquivo text not null, content_type text not null, tamanho_bytes bigint not null, storage_key text not null, sha256 text not null, extensao text not null, criado_em timestamptz not null default now());
create table if not exists integrarp.anexo_vinculo (id uuid primary key, anexo_id uuid not null references integrarp.anexo_arquivo(id), tipo text not null, entidade_id uuid not null);
create table if not exists integrarp.anexo_versao (id uuid primary key, anexo_id uuid not null references integrarp.anexo_arquivo(id), numero int not null, storage_key text not null, sha256 text not null, criado_em timestamptz not null default now());
create table if not exists integrarp.anexo_auditoria (id uuid primary key, anexo_id uuid not null references integrarp.anexo_arquivo(id), usuario_id uuid, acao text not null, criado_em timestamptz not null default now());
create table if not exists integrarp.anexo_thumbnail (id uuid primary key, anexo_id uuid not null references integrarp.anexo_arquivo(id), storage_key text not null, largura int, altura int);
create table if not exists integrarp.anexo_assinatura (id uuid primary key, anexo_id uuid not null references integrarp.anexo_arquivo(id), assinante text not null, hash_assinatura text not null, assinado_em timestamptz not null default now());
create table if not exists integrarp.anexo_configuracao (id uuid primary key, tenant_id uuid not null, extensoes_permitidas text not null, tamanho_maximo_bytes bigint not null);
create table if not exists integrarp.notificacao (id uuid primary key, tenant_id uuid not null, evento text not null, titulo text not null, corpo text not null, criado_em timestamptz not null default now());
create table if not exists integrarp.notificacao_destinatario (id uuid primary key, notificacao_id uuid not null references integrarp.notificacao(id), usuario_id uuid not null, canal text not null, status text not null, lida_em timestamptz);
create table if not exists integrarp.notificacao_preferencia (id uuid primary key, tenant_id uuid not null, usuario_id uuid not null, canal text not null, habilitado boolean not null default true);
create table if not exists integrarp.notificacao_template (id uuid primary key, tenant_id uuid not null, evento text not null, canal text not null, assunto text, corpo_template text not null);
create table if not exists integrarp.notificacao_push_log (id uuid primary key, destinatario_id uuid not null references integrarp.notificacao_destinatario(id), provedor text not null, status text not null, erro text, criado_em timestamptz not null default now());
create table if not exists integrarp.relatorio_definicao (id uuid primary key, tenant_id uuid not null, nome text not null, chave_consulta text not null, descricao text, habilitado boolean not null default true);
create table if not exists integrarp.relatorio_filtro (id uuid primary key, relatorio_id uuid not null references integrarp.relatorio_definicao(id), nome text not null, tipo text not null, obrigatorio boolean not null default false);
create table if not exists integrarp.relatorio_execucao (id uuid primary key, relatorio_id uuid not null references integrarp.relatorio_definicao(id), tenant_id uuid not null, status text not null, iniciado_em timestamptz not null default now(), finalizado_em timestamptz);
create table if not exists integrarp.relatorio_exportacao (id uuid primary key, execucao_id uuid not null references integrarp.relatorio_execucao(id), formato text not null, storage_key text not null, criado_em timestamptz not null default now(), expira_em timestamptz not null);
create table if not exists integrarp.relatorio_agendamento (id uuid primary key, relatorio_id uuid not null references integrarp.relatorio_definicao(id), cron text not null, habilitado boolean not null default true);
create index if not exists ix_formulario_definicao_tenant on integrarp.formulario_definicao(tenant_id);
create index if not exists ix_automacao_regra_tenant on integrarp.automacao_regra(tenant_id);
create index if not exists ix_anexo_arquivo_tenant on integrarp.anexo_arquivo(tenant_id);
create index if not exists ix_notificacao_tenant on integrarp.notificacao(tenant_id);
create index if not exists ix_relatorio_definicao_tenant on integrarp.relatorio_definicao(tenant_id);
create or replace view integrarp.vw_relatorios_v11 as select id, tenant_id, nome, chave_consulta from integrarp.relatorio_definicao where habilitado = true;
do $$ begin if not exists (select 1 from pg_constraint where conname='ck_formulario_campo_tipo_v11') then alter table integrarp.formulario_campo add constraint ck_formulario_campo_tipo_v11 check (tipo in ('text','textarea','number','money','date','datetime','boolean','select','multiselect','user','sector','client','product','order','financial_title','dynamic_record','file','photo','signature','gps','barcode','qrcode','rating','checklist','json','relation')); end if; end $$;
drop trigger if exists trg_v11_noop on integrarp.formulario_definicao;
create or replace function integrarp.fn_v11_noop() returns trigger language plpgsql as $$ begin return new; end $$;
create trigger trg_v11_noop before update on integrarp.formulario_definicao for each row execute function integrarp.fn_v11_noop();
